import{_ as i,C as e,c as p,o as n,aa as l,G as t}from"./chunks/framework.Cn7WEiMX.js";const q=JSON.parse('{"title":"开服之前：拒绝低端生电玩家","description":"","frontmatter":{},"headers":[],"relativePath":"guide/logical-questions/why-no-survival-surcuit.md","filePath":"guide/logical-questions/why-no-survival-surcuit.md"}'),s={name:"guide/logical-questions/why-no-survival-surcuit.md"};function h(c,a,u,d,_,m){const o=e("NolebaseGitContributors"),r=e("NolebaseGitChangelog");return n(),p("div",null,[a[0]||(a[0]=l('<h1 id="开服之前-拒绝低端生电玩家" tabindex="-1">开服之前：拒绝低端生电玩家 <a class="header-anchor" href="#开服之前-拒绝低端生电玩家" aria-label="Permalink to &quot;开服之前：拒绝低端生电玩家&quot;">​</a></h1> <h2 id="低端-生电玩家的定义" tabindex="-1">“低端”生电玩家的定义 <a class="header-anchor" href="#低端-生电玩家的定义" aria-label="Permalink to &quot;“低端”生电玩家的定义&quot;">​</a></h2> <p>在开始本章节的叙述之前，我想我有必要先规定一下“低端”生电玩家的含义。</p> <p>它指的是那些只会使用 Litematica 在服务器里放置生电建筑，缺乏自主研究与探索能力，且存在小团体倾向的玩家。</p> <p>换言之，若要对笔者的观点进行讨伐，不妨先在此之前想想看，是否需要对号入座。</p> <p>如果你能够证明你不是这样的玩家，那么这章节所讲述的内容也就自然不针对你。</p> <h2 id="_01-为什么" tabindex="-1">01 为什么？ <a class="header-anchor" href="#_01-为什么" aria-label="Permalink to &quot;01 为什么？&quot;">​</a></h2> <p>经过前一段小节对于“低端”生电玩家的定义，我想这个问题已经可以从很多个角度解释了。</p> <p>首先，遵照“只会寻找结构，再在服务器里放置”固定模式的玩家，其活跃行为有效性堪比生电玩家经常使用的假人。换言之，这类玩家的行为只能为服务器带来相当有限的活跃度。</p> <p>其次，接上一条，这样只会照搬的玩家，想必也很难根据服务器实际情况，对结构进行相应调整。进一步讲，这类玩家甚至根本不对自己建造的结构有着基本的了解，同样，也无法预估机器建造完成后对服务器带来的正面或负面影响。一个正常玩家，在深入了解服务器的机制时能够将外界传入的信息与服务器实际情况有效结合，并通过多种途径进行反馈。换言之，这样的玩家在实现目标的过程中，也帮服主进一步打磨完善服务器，能够形成有效的良性循环，还能进一步拉拢玩家与管理层之间的关系。</p> <p>最后，小团体倾向。这当然不止出现在生电玩家群体中，但其本身却是一种看似无害实则极度危险的特征，它通过渗透玩家之间的关系，将玩家分散为有限的分组，自己则成为其实际的领头者。这样做的后果在于，每当服务器进入困境，这些玩家就有可能会动员小团体内的其他成员离开服务器，让本就规模不大的社区环境雪上加霜。同样，这也是笔者不建议小规模服务器初期引入工会玩法的原因之一。</p> <p>另外，与第二点一样，相当一部分的低端生电玩家，语言素质也并不见得能够达到正常水平。可以负责任地说，恰恰是这些人低下的语言能力才拉低了生电玩家的风评。除此之外，使用不文明语言交流的玩家对服务器环境和玩家群体也有潜移默化的负面影响，这点会在之后的其他文章里详细讲述。</p> <p>综上所述，避开此类玩家，可以节省服务器性能与运营成本，还可延长运营周期，提高玩家群体质量。</p> <h2 id="_02-怎么做" tabindex="-1">02 怎么做？ <a class="header-anchor" href="#_02-怎么做" aria-label="Permalink to &quot;02 怎么做？&quot;">​</a></h2> <p>对大部分服主来说，最廉价省时的方法就是<em>一刀切</em>。对于部分手头不充裕、轮转能力弱的服主来讲，被低端玩家毁掉服务器的代价显然无法接受，因此需要采取最保守的方法，杜绝此类玩家渗入服务器。</p> <p>对于一部分精益求精的服主来说，从开启白名单验证到通过服务器守则详细规定，有许多成本及效果不一的方法可以长期避免此类玩家的入侵。</p> <h3 id="白名单验证" tabindex="-1">白名单验证 <a class="header-anchor" href="#白名单验证" aria-label="Permalink to &quot;白名单验证&quot;">​</a></h3> <p>成本相对低廉的方法。</p> <p>从第一部分可知，低端玩家的年龄群体与正常玩家差别较大，因此有时不会持有正版。通过开启正版验证的方式，可以阻止一部分低端玩家涌入，但这也可能导致一部分经济状况并不宽裕的正常乃至优质玩家被阻挡在外。</p> <p>除此之外，还可以通过人工审核放行的方式对玩家进行逐个过滤。好处是可以进一步控制玩家群体，坏处则是管理人员的成本会大幅增加，如果你无法接受自己或其他管理因此劳累，建议使用正版验证或第二种方法。</p> <h3 id="服务器守则" tabindex="-1">服务器守则 <a class="header-anchor" href="#服务器守则" aria-label="Permalink to &quot;服务器守则&quot;">​</a></h3> <p>成本适中的方法。需要一定的玩家群体基础，也需要良好的服务器环境。</p> <p>当玩家群体对服务器守则形成自觉后，就可以通过合理的规则限制生电玩家的行为。以某生存服务器举例，<strong>玩家能够建造生电机械，但不允许建造物品复制及拖慢服务器的机械</strong>。详细量化，则为玩家建造机械开机 MSPT 占用超过 50 时，对其进行临时封禁。这种机制的存在，既可以降低机械破坏服务器的可能，也可以间接优化玩家对于建造机器的选择。</p> <p>需要注意的是，一旦群体中出现刻意破坏规则的玩家，那么这些规则的权威性就会受到挑战。这就是“需要良好服务器环境”的原因所在。简单来讲，只有过滤后的玩家产生了集体观念，他们才会自觉地维护社区与规则。如果没有，破窗效应的存在会使得服务器的信用大打折扣，随后而至的就是玩家群体的流失。</p> <h3 id="代码层面限制" tabindex="-1">代码层面限制 <a class="header-anchor" href="#代码层面限制" aria-label="Permalink to &quot;代码层面限制&quot;">​</a></h3> <p>成本较高的方法。需要有充足的资金、人员支持，但对此类玩家的劝退效果最明显。</p> <p>上面提到的限制只能防君子不防小人。假如真的有狡猾的低端玩家进入服务器，代码层面的限制可以阻止他损害服务器。</p> <p>除了要熟悉了解原版的特性，服主还需要结合服务器玩家的实际情况，通过其他方式对此类被禁止的内容设计代偿机制。</p> <p>不过，这也是自由度最高的一种方法。如果你需要服务器充满特色，不妨将这些生电特性适当更改，避免低端玩家利用的同时还能为其他玩家适当增加新鲜感。</p> <h2 id="_03-后记" tabindex="-1">03 后记 <a class="header-anchor" href="#_03-后记" aria-label="Permalink to &quot;03 后记&quot;">​</a></h2> <p>对于第二部分维护玩家群体，其实米哈游系列的游戏为服主提供了一个相当不错的样板。</p> <p>虽然他们的公司常因此受玩家诟病（不过这一般是玩家本身质量参差不齐，而非方法或行动逻辑上存在问题），但这确实是一个低成本高效率的方法，可以提高玩家群体的包容度与抵抗力，让玩家能更快地自发拥护社区与服务器。</p> ',64)),t(o),t(r)])}const f=i(s,[["render",h]]);export{q as __pageData,f as default};
